"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[265],{7046:e=>{e.exports=JSON.parse('{"functions":[{"name":"_Init","desc":"Sets up and initializes the weapon by binding it to the camera and setting the RaycastParams","params":[],"returns":[],"function_type":"method","private":true,"source":{"line":156,"path":"init.luau"}},{"name":"Equip","desc":"Equips the weapon, making it visible and triggering the OnEquip hook for all registered modpacks.\\nThe viewmodel is parented to Workspace and becomes active.","params":[],"returns":[],"function_type":"method","source":{"line":201,"path":"init.luau"}},{"name":"Unequip","desc":"Unequips the weapon, hiding it and triggering the OnUnequip hook for all registered modpacks.\\nThe viewmodel is parented back to ReplicatedStorage and becomes inactive.","params":[],"returns":[],"function_type":"method","source":{"line":217,"path":"init.luau"}},{"name":"_GenerateSpread","desc":"Generates a random spread based on the weapon\'s accuracy","params":[],"returns":[{"desc":"","lua_type":"vector"}],"function_type":"method","private":true,"source":{"line":232,"path":"init.luau"}},{"name":"_UpdateLockedAngles","desc":"Recomputes the weapon\'s locked rotation angles from the camera\'s current orientation,\\nbased on which axes _Runtime.Lock has enabled. No-ops if the weapon isn\'t locked on any axis.","params":[],"returns":[],"function_type":"method","private":true,"source":{"line":248,"path":"init.luau"}},{"name":"_TransferAmmo","desc":"Moves up to `amount` rounds from Reserve into Amount, clamped to whatever\'s actually\\navailable and to the weapon\'s Max. Triggers OnAmmoChange if any rounds were transferred.","params":[{"name":"amount","desc":"How many rounds to move from Reserve into Amount","lua_type":"number"}],"returns":[],"function_type":"method","private":true,"source":{"line":268,"path":"init.luau"}},{"name":"_RunSimpleReload","desc":"Runs a Simple reload: waits the full duration, then fills ammo to Max in one transfer.","params":[{"name":"reload","desc":"","lua_type":"SimpleReloadData"}],"returns":[],"function_type":"method","private":true,"source":{"line":289,"path":"init.luau"}},{"name":"_RunStagedReload","desc":"Runs a Staged reload, walking each stage in order starting from _ReloadStageIndex\\n(so a resumed reload continues from wherever it was cancelled). Transfers ammo and\\nunlocks firing according to each stage\'s AmmoTransfer and CanFireAfter.","params":[{"name":"reload","desc":"","lua_type":"StagedReloadData"}],"returns":[],"function_type":"method","private":true,"source":{"line":313,"path":"init.luau"}},{"name":"_RunProgressiveReload","desc":"Runs a Progressive reload, repeating a single cycle and transferring AmountPerCycle\\nrounds each time until the weapon is full or reserve runs out. Firing is unlocked\\nbetween cycles.","params":[{"name":"reload","desc":"","lua_type":"ProgressiveReloadData"}],"returns":[],"function_type":"method","private":true,"source":{"line":344,"path":"init.luau"}},{"name":"_RunReload","desc":"Dispatches to the correct reload runner based on _Data.Reload.Type, then clears\\nall reload state once the runner finishes.","params":[],"returns":[],"function_type":"method","private":true,"source":{"line":369,"path":"init.luau"}},{"name":"_Fire","desc":"Fires a raycast per projectile, and triggers the OnFire and OnProjectileFire hooks.\\nWaits the duration of the weapon cooldown before returning.","params":[{"name":"amount","desc":"How many projectiles to cast this call","lua_type":"number"}],"returns":[],"function_type":"method","private":true,"source":{"line":396,"path":"init.luau"}},{"name":"_SetLock","desc":"Freezes the viewmodel\'s rotation on the given axes, capturing the current camera\\norientation as the locked angle. Pass nil to let the viewmodel rotate freely again.\\nCalled internally by SetRuntime \u2014 use `weapon:SetRuntime({ Lock = ... })` instead of calling this directly.","params":[{"name":"lock","desc":"Which axes to freeze relative to the camera, or nil to unlock","lua_type":"LockAxes?"}],"returns":[],"function_type":"method","private":true,"source":{"line":440,"path":"init.luau"}},{"name":"Reload","desc":"Begins (or resumes) the weapon\'s reload sequence. No-ops if already reloading, unequipped,\\nfull on ammo, out of reserve, aiming while CanReloadWhileAiming is false, or blocked by a\\nmodpack\'s OnBeforeReload. If a previous Staged reload was cancelled mid-stage, resumes\\nfrom that stage.","params":[],"returns":[],"function_type":"method","source":{"line":455,"path":"init.luau"}},{"name":"CancelReload","desc":"Interrupts an in-progress reload, if the current stage allows it. For a Staged reload,\\nthe stage index is preserved, so calling Reload again resumes (restarts) from the\\ninterrupted stage rather than starting over from the beginning.","params":[],"returns":[],"function_type":"method","source":{"line":488,"path":"init.luau"}},{"name":"SetRuntime","desc":"Overwrites weapon stats. Accuracy, MaxSpread, Range, Cooldown, Recoil, Offset,\\nand Lock are runtime-mutable and are written to _Runtime","params":[{"name":"changes","desc":"Partial fields to overwrite","lua_type":"{ [string]: any }"}],"returns":[],"function_type":"method","source":{"line":533,"path":"init.luau"}},{"name":"GetRuntime","desc":"Returns a shallow copy of the weapon\'s current runtime state (Lock, Offset,\\nIsAiming, Accuracy, MaxSpread, Range, Cooldown, Recoil). A copy, not the live\\ntable, so mutating the result can\'t bypass SetRuntime/SetAiming and their side effects.","params":[],"returns":[{"desc":"","lua_type":"RuntimeState"}],"function_type":"method","source":{"line":565,"path":"init.luau"}},{"name":"SetAiming","desc":"Toggles the weapon\'s aiming state and triggers OnAimStart/OnAimEnd for registered modpacks.\\nDoes not itself change any camera behavior \u2014 modpacks read Weapon._Runtime.IsAiming to react.","params":[{"name":"isAiming","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"method","source":{"line":578,"path":"init.luau"}},{"name":"SetFiring","desc":"Controls the weapon\'s firing state. When set to true, begins firing based on the weapon\'s firemode (Semi, Burst, or Auto).\\nWhen set to false, stops firing (Auto only \u2014 Semi/Burst always complete their sequence). Triggers OnFireStart\\nand OnFireEnd hooks accordingly. Only works when the weapon is equipped, not blocked by a reload, and has ammunition.","params":[{"name":"shouldFire","desc":"Whether the weapon should start or stop firing","lua_type":"boolean"}],"returns":[],"function_type":"method","source":{"line":606,"path":"init.luau"}}],"properties":[{"name":"Name","desc":"The name of the weapon","lua_type":"string","source":{"line":79,"path":"init.luau"}},{"name":"Viewmodel","desc":"The cloned viewmodel instance for this weapon","lua_type":"Model","source":{"line":85,"path":"init.luau"}},{"name":"Animator","desc":"The Motus animator for controlling weapon animations. See [the specific documentation](https://redcliffstudios.github.io/Motus/api/MotusAnimator) for usage.","lua_type":"MotusAnimator","source":{"line":91,"path":"init.luau"}}],"types":[],"name":"IgneousWeapon","desc":"Represents a weapon instance created by `Igneous.new()`. Contains methods for equipping, unequipping, and controlling weapon firing.\\nWeapons automatically handle spread, ammo management, and trigger modpack hooks at appropriate lifecycle points.","source":{"line":655,"path":"init.luau"}}')}}]);